"""Original equation transcriptions and study annotations, checked against chapter Review & Summary pages."""
import json, pathlib, re, sys
ROOT=pathlib.Path(__file__).resolve().parents[2]
chapters={}
def add(c,title,tex,refs,symbols,when):
 chapters.setdefault(c,[]).append(dict(title=title,tex=tex.split(' ;; '),references=refs.split(',') if refs else [],symbols=symbols,conditions=when))

add(1,'Density',r'\rho=\frac{m}{V}','1-8','ρ density (kg/m³); m mass (kg); V volume (m³).','Use a uniform sample or average density; use dm/dV when density varies. Convert all lengths before cubing them.')
add(1,'SI units and chain-link conversion',r'1\,\mathrm{N}=1\,\mathrm{kg\,m\,s^{-2}} ;; 1000\,\mathrm m\times\frac{1\,\mathrm{km}}{1000\,\mathrm m}=1\,\mathrm{km}','','Length m; mass kg; time s. A conversion factor represents the same physical amount in two units.','Conversion factors equal one physically. Cancel units as algebraic factors; prefixes are powers of ten, and area/volume conversions must be squared/cubed.')
add(2,'Displacement and average velocity',r'\Delta x=x_2-x_1 ;; v_{\mathrm{avg}}=\frac{\Delta x}{\Delta t}','2-1,2-2','x position (m); t time (s); v velocity (m/s).','Use signed coordinates. Average velocity uses displacement, not the total length traveled.')
add(2,'Average speed and instantaneous velocity',r's_{\mathrm{avg}}=\frac{\text{total distance}}{\Delta t} ;; v=\lim_{\Delta t\to0}\frac{\Delta x}{\Delta t}=\frac{dx}{dt}','2-3,2-4','s_avg and |v| speed (m/s); x position (m).','Speed is nonnegative. The slope of x(t) gives signed instantaneous velocity.')
add(2,'Acceleration',r'a_{\mathrm{avg}}=\frac{\Delta v}{\Delta t} ;; a=\frac{dv}{dt}=\frac{d^2x}{dt^2}','2-7,2-8,2-9','a acceleration (m/s²); v signed velocity (m/s).','Acceleration is the slope of v(t). Negative acceleration does not always mean slowing down.')
add(2,'The five constant-acceleration equations',r'v=v_0+at ;; x-x_0=v_0t+\frac12at^2 ;; v^2=v_0^2+2a(x-x_0) ;; x-x_0=\frac12(v_0+v)t ;; x-x_0=vt-\frac12at^2','2-11,2-15,2-16,2-17,2-18','x,x₀ displacement coordinates (m); v,v₀ velocities (m/s); a constant acceleration (m/s²); t elapsed time (s).','Acceleration must be constant during the whole interval. For free fall with upward positive, a=−g; neglect air resistance.')
add(3,'Components, magnitude, and direction',r'a_x=a\cos\theta,\quad a_y=a\sin\theta ;; a=\sqrt{a_x^2+a_y^2},\quad \tan\theta=\frac{a_y}{a_x}','3-5,3-6','a vector magnitude; aₓ,aᵧ signed components in the same units; θ angle from +x.','Use atan2(aᵧ,aₓ) or a quadrant check to recover direction; a ratio alone cannot identify the quadrant.')
add(3,'Vector addition and unit vectors',r'\vec a=a_x\hat i+a_y\hat j+a_z\hat k ;; \vec a+\vec b=\vec b+\vec a ;; (\vec a+\vec b)+\vec c=\vec a+(\vec b+\vec c) ;; r_x=a_x+b_x,\quad r_y=a_y+b_y,\quad r_z=a_z+b_z','3-2,3-3,3-7,3-10,3-11,3-12','î,ĵ,k̂ dimensionless orthogonal unit vectors; vector components carry the quantity’s units.','Add components along the same axes. A negative scalar reverses a vector’s direction.')
add(3,'Dot product',r'\vec a\cdot\vec b=ab\cos\phi=a_xb_x+a_yb_y+a_zb_z','3-20,3-22','φ angle between vectors; dot product has the product of their units.','The result is a scalar. Perpendicular vectors have zero dot product.')
add(3,'Cross product',r'\vec c=\vec a\times\vec b,\quad c=ab\sin\phi ;; \vec a\times\vec b=-(\vec b\times\vec a)','3-24,3-26','c magnitude of the cross product; φ smaller angle between vectors.','The result is perpendicular to the two vectors; use the right-hand rule. Parallel vectors have zero cross product.')
add(4,'Position, displacement, and velocity in space',r'\vec r=x\hat i+y\hat j+z\hat k ;; \Delta\vec r=\vec r_2-\vec r_1=\Delta x\hat i+\Delta y\hat j+\Delta z\hat k ;; \vec v_{\mathrm{avg}}=\frac{\Delta\vec r}{\Delta t},\quad \vec v=\frac{d\vec r}{dt}=v_x\hat i+v_y\hat j+v_z\hat k','4-1,4-2,4-3,4-4,4-8,4-10,4-11','r position (m); v velocity (m/s); unit vectors refer to fixed Cartesian axes.','Differentiate each coordinate separately. Instantaneous velocity is tangent to the path.')
add(4,'Acceleration in space',r'\vec a_{\mathrm{avg}}=\frac{\Delta\vec v}{\Delta t} ;; \vec a=\frac{d\vec v}{dt}=a_x\hat i+a_y\hat j+a_z\hat k','4-15,4-16,4-17','a acceleration (m/s²); v velocity vector (m/s).','Velocity can change direction even when speed is constant.')
add(4,'Projectile components',r'x-x_0=(v_0\cos\theta_0)t ;; y-y_0=(v_0\sin\theta_0)t-\frac12gt^2 ;; v_y=v_0\sin\theta_0-gt ;; v_y^2=(v_0\sin\theta_0)^2-2g(y-y_0)','4-21,4-22,4-23,4-24','v₀ launch speed (m/s); θ₀ launch angle from horizontal; g gravitational acceleration magnitude (m/s²).','Uniform gravity, no air drag, upward +y. Horizontal and vertical motion share the same elapsed time.')
add(4,'Trajectory and same-height range',r'y=x\tan\theta_0-\frac{gx^2}{2(v_0\cos\theta_0)^2} ;; R=\frac{v_0^2\sin(2\theta_0)}{g}','4-25,4-26','R horizontal range (m); x,y measured from the launch point (m).','The trajectory assumes x₀=y₀=0 and nonzero horizontal launch velocity. The range formula requires landing at launch height.')
add(4,'Uniform circular motion',r'a=\frac{v^2}{r},\quad T=\frac{2\pi r}{v}','4-34,4-35','r radius (m); v speed (m/s); T period (s).','Acceleration points inward. These are magnitudes; the velocity is tangent to the circle.')
add(4,'Relative velocity and acceleration',r'\vec v_{PA}=\vec v_{PB}+\vec v_{BA} ;; \vec a_{PA}=\vec a_{PB}','4-44,4-45','v_PA velocity of P relative to A; v_BA velocity of B relative to A (m/s).','Galilean frames translate at constant relative velocity without rotating; use component signs consistently.')
add(5,'Newton’s second law',r'\vec F_{\mathrm{net}}=m\vec a ;; F_{\mathrm{net},x}=ma_x,\quad F_{\mathrm{net},y}=ma_y,\quad F_{\mathrm{net},z}=ma_z ;; 1\,\mathrm N=1\,\mathrm{kg\,m/s^2}','5-1,5-2,5-3','F external net force (N); m constant mass (kg); a acceleration (m/s²).','Use an inertial frame and one isolated body. Zero net force implies constant velocity, which can be nonzero.')
add(5,'Gravity and weight',r'F_g=mg,\quad W=mg','5-8,5-12','F_g gravitational force magnitude (N); W weight (N); g local gravitational acceleration (m/s²).','Near Earth’s surface with approximately uniform gravity. The normal force is not automatically mg.')
add(5,'Newton’s third law',r'\vec F_{BC}=-\vec F_{CB}','','F_BC force on B from C (N); F_CB force on C from B (N).','An interaction pair acts on two different bodies and therefore does not cancel on either body’s separate free-body diagram.')
add(6,'Static and kinetic friction',r'0\le f_s\le\mu_sF_N,\quad f_{s,\max}=\mu_sF_N ;; f_k=\mu_kF_N','6-1,6-2','F_N normal force (N); f friction magnitude (N); μₛ,μₖ dimensionless coefficients.','Static friction adjusts up to its maximum; equality applies at impending slip. Kinetic friction opposes relative sliding.')
add(6,'Quadratic drag and terminal speed',r'D=\frac12C\rho Av^2 ;; v_t=\sqrt{\frac{2F_g}{C\rho A}}','6-14,6-16','D drag (N); C dimensionless drag coefficient; ρ fluid density (kg/m³); A frontal area (m²); v relative speed (m/s).','Use the quadratic-drag regime with the stated coefficient. Terminal speed follows D=F_g for downward fall without another significant vertical force.')
add(6,'Centripetal acceleration and net force',r'a=\frac{v^2}{R},\quad F_{\mathrm{radial,net}}=\frac{mv^2}{R}','6-17,6-18','R path radius (m); v speed (m/s); m mass (kg).','The inward net force comes from actual forces such as tension or gravity; do not add a separate extra centripetal force.')
add(7,'Kinetic energy and work–energy theorem',r'K=\frac12mv^2 ;; W_{\mathrm{net}}=\Delta K=K_f-K_i,\quad K_f=K_i+W_{\mathrm{net}}','7-1,7-10,7-11','K,W energy/work (J); m mass (kg); v speed (m/s).','Nonrelativistic particle motion. Sum work by all forces; positive net work raises kinetic energy.')
add(7,'Constant-force work and lifting',r'W=\vec F\cdot\vec d=Fd\cos\phi ;; W_g=mgd\cos\phi ;; \Delta K=W_a+W_g,\quad W_a=-W_g\ (\Delta K=0)','7-7,7-8,7-12,7-15,7-16','F force (N); d displacement magnitude (m); φ angle between force and displacement; W_a applied-force work (J).','The force must be constant for Fd cosφ. The gravitational angle is measured from downward gravity, not from the horizontal.')
add(7,'Spring force and spring work',r'\vec F_s=-k\vec d,\quad F_x=-kx ;; W_s=\frac12kx_i^2-\frac12kx_f^2 ;; W_s=-\frac12kx^2\quad(x_i=0)','7-20,7-21,7-25,7-26','k spring stiffness (N/m); x displacement from relaxed length (m).','Ideal linear spring within its elastic range. This is work done by the spring; quasistatic work on the spring has the opposite sign.')
add(7,'Variable-force work',r'W=\int_{x_i}^{x_f}F(x)\,dx ;; W=\int_{x_i}^{x_f}F_x\,dx+\int_{y_i}^{y_f}F_y\,dy+\int_{z_i}^{z_f}F_z\,dz','7-32,7-36','F components (N); coordinate increments (m); W work (J).','The separated form uses the book’s assumption Fₓ=Fₓ(x), Fᵧ=Fᵧ(y), F_z=F_z(z). In general integrate F·dr along the actual path.')
add(7,'Power',r'P_{\mathrm{avg}}=\frac{W}{\Delta t} ;; P=\frac{dW}{dt}=\vec F\cdot\vec v=Fv\cos\phi','7-42,7-43,7-47,7-48','P power (W=J/s); v instantaneous velocity (m/s).','Use instantaneous force and velocity for instantaneous power. A perpendicular force does no instantaneous work.')
add(8,'Conservative force and potential-energy change',r'\Delta U=-W_c=-\int_{x_i}^{x_f}F(x)\,dx ;; U_g=mgy,\quad\Delta U_g=mg(y_f-y_i) ;; U_s=\frac12kx^2','8-1,8-6,8-7,8-9,8-11','U potential energy (J); y height (m); k spring constant (N/m).','Choose a reference zero. mgy uses constant g; the spring expression uses x=0 at relaxed length.')
add(8,'Mechanical energy and conservation',r'E_{\mathrm{mec}}=K+U ;; K_2+U_2=K_1+U_1 ;; \Delta E_{\mathrm{mec}}=\Delta K+\Delta U=0','8-12,8-17,8-18','K kinetic and U potential energy (J).','Mechanical energy is conserved when only conservative forces transfer energy within the chosen isolated system.')
add(8,'Reading a potential-energy curve',r'F_x=-\frac{dU}{dx} ;; K(x)=E_{\mathrm{mec}}-U(x)','8-22,8-24','F force (N); U(x),E_mec energy (J); x position (m).','Allowed positions require K≥0. Turning points have K=0; equilibrium requires dU/dx=0, with a local minimum giving stable equilibrium.')
add(8,'Work, friction, and the full energy balance',r'W=\Delta E_{\mathrm{mec}}=\Delta K+\Delta U\quad(\text{no friction}) ;; \Delta E_{\mathrm{th}}=f_kd ;; W=\Delta E_{\mathrm{mec}}+\Delta E_{\mathrm{th}} ;; W=\Delta E_{\mathrm{mec}}+\Delta E_{\mathrm{th}}+\Delta E_{\mathrm{int}} ;; \Delta E_{\mathrm{mec}}+\Delta E_{\mathrm{th}}+\Delta E_{\mathrm{int}}=0\quad(\text{isolated}) ;; E_{\mathrm{mec},2}=E_{\mathrm{mec},1}-\Delta E_{\mathrm{th}}-\Delta E_{\mathrm{int}}','8-25,8-26,8-31,8-33,8-35,8-36,8-37','E_th thermal energy (J); E_int other internal energy (J); f_k friction (N); d sliding distance (m).','State the system boundary. f_kd assumes constant kinetic friction and gives generated thermal energy; external work may change several energy stores.')
add(8,'Energy-transfer power',r'P_{\mathrm{avg}}=\frac{\Delta E}{\Delta t},\quad P=\frac{dE}{dt}','8-40,8-41','E transferred energy (J); P power (W).','Match the sign of power to whether energy enters or leaves the chosen system.')
add(9,'Center of mass',r'\vec r_{\mathrm{com}}=\frac1M\sum_{i=1}^{n}m_i\vec r_i ;; x_{\mathrm{com}}=\frac{\sum m_ix_i}{M},\quad y_{\mathrm{com}}=\frac{\sum m_iy_i}{M},\quad z_{\mathrm{com}}=\frac{\sum m_iz_i}{M}','9-5,9-8','M=Σmᵢ total mass (kg); rᵢ positions (m).','Use mass weighting and one coordinate origin. Replace sums by mass integrals for a continuous body.')
add(9,'Momentum and external force',r'\vec F_{\mathrm{net}}=M\vec a_{\mathrm{com}} ;; \vec p=m\vec v,\quad \vec F_{\mathrm{net}}=\frac{d\vec p}{dt} ;; \vec P=M\vec v_{\mathrm{com}},\quad \vec F_{\mathrm{net}}=\frac{d\vec P}{dt}','9-14,9-22,9-23,9-25,9-27','p,P momentum (kg·m/s); M total mass (kg); F_net net external force (N).','Internal interaction forces cancel for the whole system. Treat variable-mass propulsion with a control-volume or rocket equation.')
add(9,'Impulse and repeated impacts',r'\vec J=\int_{t_i}^{t_f}\vec F(t)\,dt=\vec p_f-\vec p_i ;; J=F_{\mathrm{avg}}\Delta t ;; F_{\mathrm{avg,on\ target}}=-\frac{n}{\Delta t}\Delta p=-\frac{\Delta m}{\Delta t}\Delta v','9-30,9-31,9-32,9-35,9-37,9-40','J impulse (N·s); n number of arriving bodies; Δm arriving mass (kg); Δv change in each arriving body’s velocity (m/s).','The target force is opposite to the force on incoming material. For full reversal at the same speed, the magnitude of Δv is 2v.')
add(9,'Momentum conservation and collisions',r'\vec P_i=\vec P_f=\text{constant} ;; m_1v_{1i}+m_2v_{2i}=m_1v_{1f}+m_2v_{2f} ;; V=\frac{m_1v_{1i}+m_2v_{2i}}{m_1+m_2} ;; K_{1i}+K_{2i}=K_{1f}+K_{2f}\quad(\text{elastic})','9-42,9-43,9-50,9-51,9-77,9-78','P total momentum (kg·m/s); V shared final velocity (m/s).','Momentum conservation requires zero/negligible external impulse. The V formula is for sticking. Kinetic energy is conserved only in an elastic collision; use vector components in 2D.')
add(9,'Elastic impact on a stationary target',r'v_{1f}=\frac{m_1-m_2}{m_1+m_2}v_{1i},\quad v_{2f}=\frac{2m_1}{m_1+m_2}v_{1i}','9-67,9-68','m₁ projectile and m₂ target masses (kg); velocities signed along the collision axis (m/s).','One-dimensional elastic collision, target initially at rest, negligible external impulse.')
add(9,'Rocket equations',r'Rv_{\mathrm{rel}}=Ma ;; v_f-v_i=v_{\mathrm{rel}}\ln\frac{M_i}{M_f}','9-87,9-88','R positive fuel-consumption rate (kg/s); v_rel exhaust speed relative to rocket (m/s); M rocket mass (kg).','No external force and exhaust collinear with motion. The integrated relation uses constant exhaust speed; the book treats constant fuel-consumption rate.')
add(10,'Angular position, speed, and acceleration',r'\theta=\frac{s}{r},\quad1\,\mathrm{rev}=2\pi\,\mathrm{rad}=360^\circ ;; \Delta\theta=\theta_2-\theta_1,\quad\omega_{\mathrm{avg}}=\frac{\Delta\theta}{\Delta t},\quad\omega=\frac{d\theta}{dt} ;; \alpha_{\mathrm{avg}}=\frac{\Delta\omega}{\Delta t},\quad\alpha=\frac{d\omega}{dt}','10-1,10-2,10-4,10-5,10-6,10-7,10-8','θ radians; s arc length (m); r radius (m); ω rad/s; α rad/s².','Fixed rotation axis. Choose positive rotation consistently; angular vector directions follow the right-hand rule.')
add(10,'Constant angular acceleration',r'\omega=\omega_0+\alpha t ;; \theta-\theta_0=\omega_0t+\frac12\alpha t^2 ;; \omega^2=\omega_0^2+2\alpha(\theta-\theta_0) ;; \theta-\theta_0=\frac12(\omega_0+\omega)t ;; \theta-\theta_0=\omega t-\frac12\alpha t^2','10-12,10-13,10-14,10-15,10-16','θ angular position (rad); ω angular velocity (rad/s); α constant angular acceleration (rad/s²).','Use only when angular acceleration is constant over the interval.')
add(10,'Linear and angular variables',r's=r\theta,\quad v=r\omega ;; T=\frac{2\pi r}{v}=\frac{2\pi}{\omega} ;; a_t=r\alpha,\quad a_r=\frac{v^2}{r}=\omega^2r','10-17,10-18,10-19,10-20,10-22,10-23','r perpendicular distance from rotation axis (m); v speed (m/s); a_t tangential and a_r inward radial acceleration (m/s²).','Angles must be in radians. T is a period for steady rotation; the displayed speed relations use magnitudes.')
add(10,'Rotational inertia and energy',r'I=\sum_i m_ir_i^2=\int r^2\,dm ;; K=\frac12I\omega^2 ;; I=I_{\mathrm{com}}+Mh^2','10-33,10-34,10-35,10-36','I mass rotational inertia (kg·m²); r,h perpendicular distances (m); K energy (J).','The parallel-axis theorem requires a parallel axis through the center of mass for I_com. Use the inertia about the actual rotation axis.')
add(10,'Torque and rotational dynamics',r'\tau=rF\sin\phi=rF_t=r_\perp F ;; \tau_{\mathrm{net}}=I\alpha','10-39,10-40,10-41,10-45','τ torque (N·m); F force (N); φ angle between r and F; I rotational inertia (kg·m²).','Fixed-axis rigid-body rotation. Choose torque signs before summing; the lever arm is perpendicular to the force line.')
add(10,'Rotational work and power',r'W=\int_{\theta_i}^{\theta_f}\tau\,d\theta ;; W=\tau(\theta_f-\theta_i)\quad(\tau\text{ constant}) ;; P=\frac{dW}{dt}=\tau\omega ;; W_{\mathrm{net}}=\Delta K=\frac12I\omega_f^2-\frac12I\omega_i^2','10-52,10-53,10-54,10-55','W,K energy (J); P power (W); θ radians.','Constant I and a fixed axis. Integrate variable torque; use the net torque’s work for the kinetic-energy change.')
add(11,'Rolling without slipping',r'v_{\mathrm{com}}=\omega R,\quad a_{\mathrm{com}}=\alpha R ;; K=\frac12I_{\mathrm{com}}\omega^2+\frac12Mv_{\mathrm{com}}^2 ;; a_{\mathrm{com},x}=-\frac{g\sin\theta}{1+I_{\mathrm{com}}/(MR^2)}','11-2,11-5,11-6,11-10','R rolling radius (m); M mass (kg); θ ramp angle; x positive uphill.','Rigid body rolling without slipping. The downhill acceleration formula assumes no other driving torque or dissipative loss and enough static friction.')
add(11,'Torque and a particle’s angular momentum',r'\vec\tau=\vec r\times\vec F,\quad\tau=rF\sin\phi=rF_\perp=r_\perp F ;; \vec\ell=\vec r\times\vec p=m(\vec r\times\vec v) ;; \ell=rmv\sin\phi=rp_\perp=r_\perp p','11-14,11-15,11-16,11-17,11-18,11-19,11-20,11-21','τ torque (N·m); ℓ angular momentum (kg·m²/s); r measured from the chosen origin (m).','Torque and angular momentum must be defined about the same fixed origin; use the right-hand rule.')
add(11,'Angular-momentum balance and conservation',r'\vec\tau_{\mathrm{net}}=\frac{d\vec\ell}{dt} ;; \vec L=\sum_{i=1}^{n}\vec\ell_i,\quad\vec\tau_{\mathrm{ext,net}}=\frac{d\vec L}{dt} ;; L_z=I\omega ;; \vec L_i=\vec L_f=\text{constant}\quad(\vec\tau_{\mathrm{ext,net}}=0)','11-23,11-26,11-29,11-31,11-32,11-33','L angular momentum (kg·m²/s); I inertia (kg·m²).','L_z=Iω is the component along a fixed axis. Conservation requires zero net external torque, not merely zero net external force.')
add(11,'Gyroscope precession',r'\Omega=\frac{Mgr}{I\omega}','11-46','Ω precession rate (rad/s); ω spin rate (rad/s); r gravity’s lever arm (m); M mass (kg).','Steady, slow precession of a rapidly spinning gyroscope; I is the inertia about its spin axis.')
add(12,'Static equilibrium',r'\vec F_{\mathrm{net}}=0,\quad\vec\tau_{\mathrm{net}}=0 ;; F_{\mathrm{net},x}=0,\quad F_{\mathrm{net},y}=0,\quad\tau_{\mathrm{net},z}=0','12-3,12-5,12-7,12-8,12-9','F forces (N); τ torques (N·m).','A body at rest in equilibrium must balance both force and torque. The component version is planar; choose any convenient moment center.')
add(12,'Tension, compression, and shear',r'\text{stress}=\text{modulus}\times\text{strain} ;; \frac FA=E\frac{\Delta L}{L} ;; \frac FA=G\frac{\Delta x}{L}','12-22,12-23,12-24','E Young’s modulus and G shear modulus (Pa); F/A stress (Pa); ΔL/L and Δx/L dimensionless strains.','Small, linearly elastic deformation. Use the appropriate area and modulus; ΔL for axial change and Δx for lateral shear.')
add(12,'Bulk compression',r'p=B\frac{|\Delta V|}{V}','12-25','p compressive pressure increase (Pa); B bulk modulus (Pa); V volume (m³).','The chapter uses the magnitude of volume reduction. With signed ΔV, write Δp=−BΔV/V.')
add(13,'Universal gravitation and superposition',r'F=G\frac{m_1m_2}{r^2} ;; \vec F_{1,\mathrm{net}}=\sum_{i=2}^{n}\vec F_{1i},\quad\vec F=\int d\vec F','13-1,13-5,13-6','G≈6.67×10⁻¹¹ N·m²/kg²; m masses (kg); r center-to-center separation (m).','Point masses or exterior points of spherically symmetric bodies. Forces attract; add vectors, not just magnitudes.')
add(13,'Gravity outside and inside a sphere',r'F=ma_g,\quad a_g=\frac{GM}{r^2} ;; F=\frac{GmM}{R^3}r\quad(r<R)','13-10,13-11,13-19','M source mass (kg); R sphere radius and r radial position (m); a_g gravitational acceleration magnitude (m/s²).','The interior relation requires uniform volume density. A uniform thin spherical shell gives zero field inside; terrestrial measured g also includes rotation effects.')
add(13,'Gravitational potential energy',r'U=-\frac{GMm}{r} ;; U=-G\left(\frac{m_1m_2}{r_{12}}+\frac{m_1m_3}{r_{13}}+\frac{m_2m_3}{r_{23}}\right)','13-21,13-22','U potential energy (J); r separation (m).','Set U=0 at infinite separation. Count each pair once; U is a scalar sum.')
add(13,'Escape speed and orbital period',r'v_{\mathrm{esc}}=\sqrt{\frac{2GM}{R}} ;; T^2=\frac{4\pi^2}{GM}a^3','13-28,13-34','v_esc speed (m/s); T period (s); a orbital semimajor axis (m); M central mass (kg).','Escape from surface radius R with no drag, thrust, or other gravitating body. Kepler’s period law uses a for an ellipse and r=a for a circle; central mass dominates.')
add(13,'Energy of an orbit',r'U=-\frac{GMm}{r},\quad K=\frac{GMm}{2r},\quad E=-\frac{GMm}{2r}\quad(\text{circular}) ;; E=-\frac{GMm}{2a}\quad(\text{elliptical})','13-21,13-38,13-40,13-42','E mechanical, K kinetic, U potential energy (J); a semimajor axis (m).','Circular kinetic energy expression is not valid pointwise on an ellipse. Negative total orbital energy describes a bound orbit.')
add(14,'Density and pressure',r'\rho=\frac{\Delta m}{\Delta V}=\frac mV\quad(\text{uniform}) ;; p=\frac{\Delta F_\perp}{\Delta A}=\frac FA\quad(\text{uniform})','14-1,14-2,14-3,14-4','ρ density (kg/m³); p pressure (Pa=N/m²); A area (m²).','Pressure acts normal to the surface. Gauge pressure is absolute pressure minus atmospheric pressure.')
add(14,'Hydrostatic pressure',r'p_2=p_1+\rho g(y_1-y_2) ;; p=p_0+\rho gh','14-7,14-8','h positive depth (m); y positive upward (m); ρ constant density (kg/m³).','Fluid at rest, approximately constant g and density. Pressure changes imposed on a confined fluid transmit throughout it (Pascal’s principle).')
add(14,'Buoyancy and apparent weight',r'F_b=m_fg=\rho_fV_{\mathrm{displaced}}g ;; W_{\mathrm{app}}=W-F_b','14-16,14-19','m_f displaced-fluid mass (kg); V_displaced volume (m³); buoyant force F_b (N).','Buoyancy is upward. A freely floating body balances weight with buoyancy; use submerged volume, not automatically total object volume.')
add(14,'Continuity and flow rates',r'R_V=Av=\text{constant} ;; R_m=\rho R_V=\rho Av=\text{constant}','14-24,14-25','R_V volumetric flow (m³/s); R_m mass flow (kg/s); A cross section (m²); v average speed (m/s).','Steady flow through one streamtube without leaks. Constant Av additionally requires incompressibility.')
add(14,'Bernoulli’s equation',r'p+\frac12\rho v^2+\rho gy=\text{constant}','14-29','Each term has units of pressure (Pa); v speed (m/s); y elevation (m).','Steady incompressible inviscid flow along a streamline, without shaft-work addition or dissipative losses.')
add(15,'Frequency, period, and SHM kinematics',r'f=\frac1T,\quad\omega=2\pi f=\frac{2\pi}{T} ;; x=x_m\cos(\omega t+\phi) ;; v=-\omega x_m\sin(\omega t+\phi) ;; a=-\omega^2x_m\cos(\omega t+\phi)=-\omega^2x','15-1,15-2,15-3,15-5,15-6,15-7','f frequency (Hz); T period (s); ω rad/s; x_m amplitude (m); φ phase constant (rad).','Simple harmonic motion about equilibrium. Differentiate the same phase; acceleration points opposite displacement.')
add(15,'Mass–spring oscillator and energy',r'\omega=\sqrt{\frac km},\quad T=2\pi\sqrt{\frac mk} ;; K=\frac12mv^2,\quad U=\frac12kx^2,\quad E=\frac12kx_m^2','15-12,15-13','k spring stiffness (N/m); m mass (kg); K,U,E energy (J).','Ideal Hooke’s-law spring without damping; E stays constant while K and U exchange.')
add(15,'Torsion, simple, and physical pendulums',r'T_{\mathrm{torsion}}=2\pi\sqrt{\frac I\kappa} ;; T_{\mathrm{simple}}=2\pi\sqrt{\frac Lg} ;; T_{\mathrm{physical}}=2\pi\sqrt{\frac I{mgh}}','15-23,15-28,15-29','I inertia about pivot (kg·m²); κ torsional constant (N·m/rad); L string length and h pivot-to-COM distance (m).','Small-angle oscillations. For the physical pendulum, use inertia about the pivot, not about the center of mass.')
add(15,'Damping and resonance',r'F_d=-bv ;; x(t)=x_me^{-bt/(2m)}\cos(\omega^{\prime}t+\phi) ;; \omega^{\prime}=\sqrt{\frac km-\frac{b^2}{4m^2}} ;; E(t)\approx\frac12kx_m^2e^{-bt/m} ;; \omega_d=\omega\quad(\text{velocity-amplitude resonance})','15-42,15-43,15-44,15-46','b damping coefficient (kg/s); ω′ damped angular frequency; ω_d drive angular frequency (rad/s).','Displacement form requires underdamping. The energy envelope is a weak-damping approximation. The displacement-amplitude maximum is only approximately at the undamped natural frequency.')
add(16,'Traveling-wave shape and speed',r'y(x,t)=y_m\sin(kx-\omega t) ;; k=\frac{2\pi}{\lambda},\quad f=\frac{\omega}{2\pi}=\frac1T ;; v=\frac\omega k=\frac\lambda T=\lambda f ;; y(x,t)=h(kx\mp\omega t)','16-2,16-5,16-9,16-13,16-17','y,y_m displacement and amplitude (m); k angular wave number (rad/m); ω rad/s; λ wavelength (m); v wave speed (m/s).','The minus sign travels toward +x; the plus sign toward −x. Wave speed is not the transverse particle velocity.')
add(16,'String speed and transmitted power',r'v=\sqrt{\frac\tau\mu} ;; P_{\mathrm{avg}}=\frac12\mu v\omega^2y_m^2','16-26,16-33','τ string tension (N); μ linear mass density (kg/m); P_avg power (W).','Small-amplitude transverse waves on a uniform taut string. The power formula is for a sinusoidal traveling wave.')
add(16,'Superposition and interference',r'y_{\mathrm{net}}=\sum_jy_j ;; y^{\prime}(x,t)=2y_m\cos\frac\phi2\,\sin\left(kx-\omega t+\frac\phi2\right)','16-51','φ relative phase (rad); each wave has amplitude y_m (m).','Linear superposition. The combined sinusoid assumes equal amplitudes, equal frequencies, and the same travel direction; resultant amplitude is |2y_m cos(φ/2)|.')
add(16,'Standing waves and string resonances',r'y^{\prime}(x,t)=2y_m\sin(kx)\cos(\omega t) ;; f_n=\frac{nv}{2L},\quad n=1,2,3,\ldots','16-60,16-66','L vibrating string length (m); n positive integer harmonic; v wave speed (m/s).','Opposite traveling waves of equal amplitude and frequency. A string fixed at both ends has displacement nodes at both ends.')
add(17,'Sound speed, displacement, and pressure',r'v=\sqrt{\frac B\rho} ;; s=s_m\cos(kx-\omega t) ;; \Delta p=\Delta p_m\sin(kx-\omega t),\quad\Delta p_m=\rho v\omega s_m','17-3,17-12,17-13,17-14','B bulk modulus (Pa); ρ density (kg/m³); s_m displacement amplitude (m); Δp_m pressure amplitude (Pa).','Small-amplitude longitudinal waves in a uniform medium. Pressure and displacement at a point differ in phase by π/2.')
add(17,'Path difference and sound interference',r'\phi=\frac{2\pi\Delta L}{\lambda} ;; \phi=2\pi m,\quad\Delta L=m\lambda\quad(\text{constructive}) ;; \phi=(2m+1)\pi,\quad\Delta L=(m+\tfrac12)\lambda\quad(\text{destructive})','17-21,17-22,17-23,17-24,17-25','ΔL path difference (m); λ wavelength (m); m=0,1,2,… .','Sources start in phase and have the same frequency; include any source phase offset separately.')
add(17,'Sound intensity and decibels',r'I=\frac PA=\frac12\rho v\omega^2s_m^2 ;; I=\frac{P_s}{4\pi r^2} ;; \beta=(10\,\mathrm{dB})\log_{10}\frac I{I_0},\quad I_0=10^{-12}\,\mathrm{W/m^2}','17-26,17-27,17-28,17-29','I intensity (W/m²); P_s source power (W); r distance (m); β sound level (dB).','Inverse-square spreading assumes an isotropic point source without absorption/reflections. Decibels use base-10 logarithms of intensity ratios.')
add(17,'Pipe resonances and beats',r'f_n=\frac{nv}{2L},\quad n=1,2,3,\ldots\quad(\text{open–open}) ;; f_n=\frac{nv}{4L},\quad n=1,3,5,\ldots\quad(\text{closed–open}) ;; f_{\mathrm{beat}}=|f_1-f_2|','17-39,17-41,17-46','L effective air-column length (m); v sound speed (m/s); f frequencies (Hz).','Ideal pipe ends; real end corrections can shift resonances. Beats require two nearby frequencies; the beat rate is nonnegative.')
add(17,'Doppler effect and shock cone',r'f^{\prime}=f\frac{v\pm v_D}{v\mp v_S} ;; \sin\theta=\frac v{v_S}\quad(v_S>v)','17-47,17-57','v sound speed in medium (m/s); v_D detector and v_S source speeds relative to medium; θ Mach-cone half-angle.','For approach, use +v_D in the numerator and −v_S in the denominator; reverse each sign for recession. Ordinary sound Doppler formula excludes a supersonic source crossing a shock.')
add(18,'Gas thermometer and temperature scales',r'T=T_3\lim_{n\to0}\frac p{p_3},\quad T_3=273.16\,\mathrm K ;; T_C=T-273.15,\quad T_F=\frac95T_C+32','18-6,18-7,18-8','T kelvins; T_C °C; T_F °F; p,p₃ pressures (Pa) of a fixed-volume dilute gas at measurement and calibration states.','The first relation is the book’s gas-thermometer calibration, not a statement of the current SI definition. Temperature differences of 1 K and 1 °C have equal size.')
add(18,'Thermal expansion',r'\Delta L=L\alpha\Delta T ;; \Delta V=V\beta\Delta T,\quad\beta=3\alpha','18-9,18-10','α linear and β volume expansion coefficients (K⁻¹); L length (m); V volume (m³).','Small temperature interval with approximately constant coefficients. β=3α assumes an isotropic solid and small strain.')
add(18,'Heat capacity and phase change',r'Q=C(T_f-T_i)=cm(T_f-T_i) ;; Q=Lm ;; 1\,\mathrm{cal}=4.1868\,\mathrm J=3.968\times10^{-3}\,\mathrm{Btu}','18-12,18-13,18-14,18-16','C heat capacity (J/K); c specific heat (J/(kg·K)); L latent heat (J/kg); m mass (kg).','Sensible-heat formula assumes no phase change and nearly constant c. During the phase change, use the appropriate fusion/vaporization latent heat; choose the sign for absorption or release. The calorie conversion is the book’s convention.')
add(18,'Boundary work and the first law',r'W=\int_{V_i}^{V_f}p\,dV ;; \Delta E_{\mathrm{int}}=Q-W,\quad dE_{\mathrm{int}}=\delta Q-\delta W','18-25,18-26,18-27','Q heat entering system (J); W work done by system (J); E_int internal energy (J); p pressure (Pa); V volume (m³).','Use the chapter’s sign convention: expansion work is positive. The integral uses a quasistatic pressure or the resisting boundary pressure; heat and work depend on the path.')
add(18,'Special thermodynamic processes',r'Q=0\Rightarrow\Delta E_{\mathrm{int}}=-W\quad(\text{adiabatic}) ;; W=0\Rightarrow\Delta E_{\mathrm{int}}=Q\quad(\text{fixed volume}) ;; \Delta E_{\mathrm{int}}=0\Rightarrow Q=W\quad(\text{cycle}) ;; Q=W=0\Rightarrow\Delta E_{\mathrm{int}}=0\quad(\text{isolated free expansion})','','Q,W,ΔE_int energy (J).','For free expansion, the external resisting pressure is zero. A general adiabatic process need not be isentropic.')
add(18,'Conduction and thermal radiation',r'P_{\mathrm{cond}}=\frac Qt=kA\frac{T_H-T_C}{L} ;; P_{\mathrm{rad}}=\sigma\epsilon AT^4,\quad P_{\mathrm{abs}}=\sigma\epsilon AT_{\mathrm{env}}^4','18-32,18-38,18-39','k thermal conductivity (W/(m·K)); σ≈5.6704×10⁻⁸ W/(m²·K⁴); ε emissivity; A area (m²).','Steady 1D conduction through a slab. Radiation temperatures must be kelvins; the absorption form assumes the stated uniform surrounding radiation field and matching absorptivity/emissivity.')
add(19,'Moles and molecular mass',r'N_A\approx6.02\times10^{23}\,\mathrm{mol^{-1}} ;; n=\frac N{N_A}=\frac{M_{\mathrm{sam}}}{M}=\frac{M_{\mathrm{sam}}}{mN_A} ;; M=mN_A','19-1,19-2,19-3,19-4','n amount (mol); N particle count; M molar mass (kg/mol); m molecular mass (kg); M_sam sample mass (kg).','Keep molar mass in kg/mol when using SI gas equations. The displayed Avogadro value is rounded as in the chapter.')
add(19,'Ideal gas law and isothermal work',r'pV=nRT=NkT,\quad k=\frac R{N_A} ;; W=nRT\ln\frac{V_f}{V_i}','19-5,19-7,19-9,19-14','R≈8.31 J/(mol·K); k≈1.38×10⁻²³ J/K; p absolute pressure (Pa); V volume (m³); T absolute temperature (K).','Dilute ideal gas. The logarithmic work is for a quasistatic isothermal process, with work positive on expansion.')
add(19,'Molecular speeds and kinetic energy',r'p=\frac{nMv_{\mathrm{rms}}^2}{3V} ;; v_{\mathrm{rms}}=\sqrt{\frac{3RT}{M}} ;; K_{\mathrm{avg}}=\frac32kT ;; v_{\mathrm{avg}}=\sqrt{\frac{8RT}{\pi M}},\quad v_P=\sqrt{\frac{2RT}{M}}','19-21,19-22,19-24,19-31,19-35','v speeds (m/s); M molar mass (kg/mol); K_avg translational kinetic energy per molecule (J).','Ideal gas in thermal equilibrium. RMS, mean, and most-probable speed are different averages of the same distribution.')
add(19,'Mean free path and Maxwell distribution',r'\lambda=\frac1{\sqrt2\pi d^2(N/V)} ;; P(v)=4\pi\left(\frac M{2\pi RT}\right)^{3/2}v^2e^{-Mv^2/(2RT)}','19-25,19-27','λ path length (m); d molecular collision diameter (m); N/V number density (m⁻³); P(v) probability density (s/m).','Dilute gas with hard-sphere collisions and Maxwell–Boltzmann equilibrium. P(v)dv, not P(v) alone, is a probability.')
add(19,'Molar heat capacities and equipartition',r'C_V=\frac Q{n\Delta T}=\frac{\Delta E_{\mathrm{int}}}{n\Delta T}\quad(V\text{ constant}) ;; C_p=\frac Q{n\Delta T}\quad(p\text{ constant}),\quad C_p=C_V+R ;; C_V=\frac32R\quad(\text{monatomic}),\quad C_V=\frac f2R ;; E_{\mathrm{int}}=nC_VT,\quad\Delta E_{\mathrm{int}}=nC_V\Delta T','19-39,19-41,19-43,19-44,19-45,19-46,19-49,19-51','C_V,C_p molar heat capacities (J/(mol·K)); f active degrees of freedom; E_int energy (J).','Ideal gas with constant active degrees of freedom/heat capacity over the interval. f=3 for monatomic translation and often 5 for a diatomic gas before vibration becomes active.')
add(19,'Adiabatic gas relation',r'pV^\gamma=\text{constant},\quad\gamma=\frac{C_p}{C_V}','19-53','p absolute pressure (Pa); V volume (m³); γ dimensionless heat-capacity ratio.','Reversible/quasistatic adiabatic ideal-gas change with constant γ. Do not use for irreversible free expansion; an ideal gas in isolated free expansion instead keeps temperature and pV constant.')
add(20,'Entropy change along a reversible reference path',r'\Delta S=\int_i^f\frac{\delta Q_{\mathrm{rev}}}{T} ;; \Delta S=\frac{Q_{\mathrm{rev}}}{T}\quad(T\text{ constant}) ;; \Delta S\approx\frac Q{T_{\mathrm{avg}}}','20-1,20-2,20-3','S entropy (J/K); Q reversible-path heat (J); T absolute temperature (K).','Entropy is a state function. For an irreversible process, evaluate a reversible path between the same end states. The average-temperature estimate needs a small temperature change and an appropriate reversible heat exchange.')
add(20,'Ideal-gas entropy and the second law',r'\Delta S=nR\ln\frac{V_f}{V_i}+nC_V\ln\frac{T_f}{T_i} ;; \Delta S_{\mathrm{isolated}}\ge0','20-4,20-5','n moles; C_V molar heat capacity (J/(mol·K)); T temperatures (K); V volumes (m³).','Ideal gas with constant C_V. The entropy inequality applies to an isolated system, or system plus surroundings; a subsystem can lose entropy by heat transfer.')
add(20,'Engine efficiency and Carnot limit',r'\eta=\frac{|W|}{|Q_H|} ;; \eta_C=1-\frac{|Q_L|}{|Q_H|}=1-\frac{T_L}{T_H}','20-11,20-12,20-13','Q_H,Q_L heat exchanged with hot/cold reservoirs (J); W work output (J); T_H,T_L absolute temperatures (K).','Cyclic heat engine operating between two reservoirs. Carnot equality requires reversible operation; real engines fall below the bound.')
add(20,'Refrigerator performance',r'K=\frac{|Q_L|}{|W|} ;; K_C=\frac{|Q_L|}{|Q_H|-|Q_L|}=\frac{T_L}{T_H-T_L}','20-14,20-15,20-16','K coefficient of performance (dimensionless); Q_L extracted cold-side heat (J); W work input (J).','Use refrigerator COP, not heat-engine efficiency. Carnot COP assumes reversible operation between fixed Kelvin temperatures.')
add(20,'Multiplicity and statistical entropy',r'\mathcal{W}=\frac{N!}{n_1!n_2!} ;; S=k\ln\mathcal{W}','20-20,20-21','𝒲 multiplicity (dimensionless count); n₁+n₂=N; k Boltzmann constant (J/K).','The binomial count assigns N molecules between two regions. Boltzmann entropy assumes equiprobable compatible microstates; 𝒲 here is not work.')
add(21,'Current, Coulomb force, and elementary charge',r'i=\frac{dq}{dt} ;; F=\frac1{4\pi\epsilon_0}\frac{|q_1q_2|}{r^2} ;; q=ne,\quad e\approx1.602\times10^{-19}\,\mathrm C','21-3,21-4','i current (A=C/s); q charges (C); n signed integer; r separation (m); ε₀≈8.85×10⁻¹² C²/(N·m²).','Coulomb force magnitude for point charges at rest or sufficiently slow. Like signs repel, unlike attract; add multiple forces as vectors. Net charge of an isolated system is conserved.')
add(22,'Electric field and force on a charge',r'\vec E=\frac{\vec F}{q_0},\quad\vec F=q\vec E ;; E=\frac1{4\pi\epsilon_0}\frac{|q|}{r^2}','22-1,22-3,22-28','E electric field (N/C=V/m); F force (N); q charge (C); r distance (m).','Define E with a positive nonperturbing test charge. A negative charge’s force is opposite E. Point-charge field is radial; superpose field vectors.')
add(22,'Electric dipole and far-axis field',r'p=qd,\quad E_{\mathrm{axis}}=\frac1{2\pi\epsilon_0}\frac p{z^3}','22-9','p dipole moment (C·m); d charge separation (m); z axial distance from center (m).','Equal and opposite charges; dipole vector points from −q to +q. Far-field approximation requires z≫d; it is not the equatorial field formula.')
add(22,'Uniformly charged disk',r'E=\frac{\sigma}{2\epsilon_0}\left(1-\frac z{\sqrt{z^2+R^2}}\right)','22-26','σ surface charge density (C/m²); R disk radius and z positive axial distance (m).','Magnitude form on the axis of a thin uniformly charged disk for σ≥0,z>0; choose direction from charge sign and the side of the disk.')
add(22,'Torque and energy of an electric dipole',r'\vec\tau=\vec p\times\vec E ;; U=-\vec p\cdot\vec E=-pE\cos\theta','22-34,22-38','τ torque (N·m); p dipole moment (C·m); U orientation energy (J).','Uniform external electric field and a fixed dipole moment. U=0 when perpendicular; aligned orientation minimizes U.')
add(23,'Electric flux and Gauss’ law',r'\Phi_E=\oint_S\vec E\cdot d\vec A ;; \epsilon_0\Phi_E=q_{\mathrm{enc}}','23-4,23-6','Φ_E flux (N·m²/C); q_enc net enclosed charge (C); outward area vector dA (m²).','The Gaussian surface must be closed. External charges may change local E but contribute zero net closed-surface flux.')
add(23,'Conductors, infinite line, and infinite sheet',r'E_{\mathrm{surface}}=\frac{|\sigma|}{\epsilon_0},\quad E_{\mathrm{inside\ conductor}}=0 ;; E_{\mathrm{line}}=\frac{|\lambda|}{2\pi\epsilon_0r} ;; E_{\mathrm{sheet}}=\frac{|\sigma|}{2\epsilon_0}','23-11,23-12,23-13','λ linear density (C/m); σ surface density (C/m²); r distance from line (m).','Conductor in electrostatic equilibrium; field is immediately outside its surface. Infinite line/sheet formulas need those symmetries and are magnitudes; direction follows sign.')
add(23,'Spherical shell and uniform solid sphere',r'E=\frac1{4\pi\epsilon_0}\frac{|q|}{r^2}\quad(r>R) ;; E_{\mathrm{shell}}=0\quad(r<R) ;; E_{\mathrm{solid}}=\frac{|q|r}{4\pi\epsilon_0R^3}\quad(r<R)','23-15,23-16,23-20','R source radius and r radial observation distance (m); q total charge (C).','Shell surface charge must be uniform; the solid-sphere interior formula instead requires uniform volume charge. Exterior field is that of the total charge at the center.')
add(24,'Potential, electric energy, and work',r'V=-\frac{W_\infty}{q_0}=\frac U{q_0} ;; U=qV,\quad\Delta U=q\Delta V ;; \Delta K=-q\Delta V ;; \Delta K=-q\Delta V+W_{\mathrm{app}} ;; W_{\mathrm{app}}=q\Delta V\quad(\Delta K=0)','24-2,24-3,24-4,24-9,24-11,24-12','V potential (V=J/C); W_∞ work by the field from infinity; U,K,W energy (J); q charge (C).','The −qΔV term is work by the electric field. W_app=qΔV requires unchanged kinetic energy; do not confuse potential with potential energy.')
add(24,'Potential from field and field from potential',r'V_f-V_i=-\int_i^f\vec E\cdot d\vec s ;; V=-\int_i^f\vec E\cdot d\vec s\quad(V_i=0) ;; \Delta V=-E\Delta x\quad(\text{uniform, along }\vec E) ;; E_s=-\frac{\partial V}{\partial s} ;; E_x=-\frac{\partial V}{\partial x},\quad E_y=-\frac{\partial V}{\partial y},\quad E_z=-\frac{\partial V}{\partial z} ;; E_s=-\frac{\Delta V}{\Delta s}\quad(\text{uniform})','24-18,24-19,24-21,24-40,24-41,24-42','E field (V/m); V potential (V); s,x,y,z coordinates (m).','Electrostatics: potential differences are path independent, and E is perpendicular to equipotentials. The finite-difference field relation requires a uniform field along the chosen coordinate.')
add(24,'Point charges, charge distributions, and dipoles',r'V=\frac1{4\pi\epsilon_0}\frac q r ;; V=\sum_iV_i=\frac1{4\pi\epsilon_0}\sum_i\frac{q_i}{r_i} ;; V=\frac1{4\pi\epsilon_0}\int\frac{dq}{r} ;; V_{\mathrm{dipole}}=\frac1{4\pi\epsilon_0}\frac{p\cos\theta}{r^2}','24-26,24-27,24-30,24-32','p=qd electric dipole moment (C·m); r distance (m); θ angle from dipole axis.','Signed scalar potentials add. Set zero at infinity for localized charges; the dipole approximation needs r≫d. The continuous integral measures r from each charge element to the observation point.')
add(24,'Two-charge potential energy and conductors',r'U=W=\frac1{4\pi\epsilon_0}\frac{q_1q_2}{r}','24-46','U assembly energy (J); q₁,q₂ signed charges (C); r separation (m).','Bring initially separated stationary charges together quasistatically from infinity. Electrostatic conductors have uniform potential throughout their interior and surface, even when that potential is nonzero.')
add(25,'Capacitance and standard geometries',r'q=CV ;; C_{\mathrm{plates}}=\epsilon_0\frac A d ;; C_{\mathrm{cylinders}}=\frac{2\pi\epsilon_0L}{\ln(b/a)} ;; C_{\mathrm{spheres}}=4\pi\epsilon_0\frac{ab}{b-a} ;; C_{\mathrm{isolated\ sphere}}=4\pi\epsilon_0R','25-1,25-9,25-14,25-17,25-18','C capacitance (F=C/V); q plate-charge magnitude (C); V plate voltage magnitude (V); a<b radii, L length, d gap (m); A area (m²).','Vacuum between ideal conductors. Neglect edge effects for broad parallel plates or long coaxial cylinders; isolated-sphere potential is relative to infinity.')
add(25,'Capacitors in parallel and series',r'C_{\mathrm{eq}}=\sum_{j=1}^{n}C_j\quad(\text{parallel}) ;; \frac1{C_{\mathrm{eq}}}=\sum_{j=1}^{n}\frac1{C_j}\quad(\text{series})','25-19,25-20','C_j,C_eq capacitances (F).','Parallel capacitors share voltage; ideal series capacitors share charge magnitude when intermediate nodes carry no added net charge.')
add(25,'Capacitor energy and field energy density',r'U=\frac{q^2}{2C}=\frac12CV^2 ;; u=\frac12\epsilon_0E^2','25-21,25-22,25-25','U stored energy (J); u energy density (J/m³); E field (V/m).','Linear vacuum capacitor. Energy density is local; do not confuse u (per volume) with total U.')
add(25,'Dielectrics and Gauss’ law',r'C=\kappa C_0 ;; \epsilon_0\oint_S\kappa\vec E\cdot d\vec A=q_{\mathrm{free}}','25-36','κ relative permittivity (dimensionless); C₀ vacuum capacitance (F); q_free free enclosed charge (C).','Linear dielectric completely filling the relevant gap for C=κC₀. Keep κ inside the flux integral if it varies. When inserting a dielectric, check whether charge is fixed or a battery maintains voltage.')
add(26,'Current, current density, and drift',r'i=\frac{dq}{dt}=\int_S\vec J\cdot d\vec A ;; \vec J=ne\vec v_d','26-1,26-4,26-7','i current (A); J current density (A/m²); n carrier number density (m⁻³); e charge magnitude (C); v_d drift velocity (m/s).','The displayed drift-vector expression follows the book’s positive-carrier convention. For electrons use J=nqv_d with q=−e, so electron drift opposes conventional current.')
add(26,'Resistance, resistivity, and conductivity',r'R=\frac Vi,\quad\rho=\frac EJ=\frac1\sigma ;; \vec E=\rho\vec J ;; R=\rho\frac L A','26-8,26-10,26-11,26-12,26-16','R resistance (Ω); ρ resistivity (Ω·m); σ conductivity (S/m); L length (m); A cross section (m²).','Uniform ohmic material and cross section for ρL/A. R=V/i defines a ratio; Ohm’s law additionally requires resistance independent of applied voltage under fixed conditions.')
add(26,'Temperature dependence and microscopic resistivity',r'\rho-\rho_0=\rho_0\alpha(T-T_0) ;; \rho=\frac{m}{ne^2\tau}','26-17,26-22','α temperature coefficient (K⁻¹); m electron mass (kg); τ mean collision time (s); n free-electron density (m⁻³).','Linear temperature approximation over the specified interval. The microscopic formula uses the classical relaxation-time model; ρ is electrical resistivity, not mass density.')
add(26,'Electrical power and resistor heating',r'P=iV ;; P=i^2R=\frac{V^2}{R}','26-26,26-27,26-28','P power (W); i current (A); V potential difference (V); R resistance (Ω).','Use the passive sign convention for absorbed power. The i²R and V²/R forms apply to resistive dissipation, not to every electrical device.')
add(27,'Emf, loop rule, and junction rule',r'\mathcal{E}=\frac{dW}{dq} ;; \sum_{\mathrm{loop}}\Delta V=0 ;; \sum i_{\mathrm{in}}=\sum i_{\mathrm{out}}','27-1','ℰ emf (V); W source work (J); q charge (C); i current (A).','For a resistor, walking with current gives ΔV=−iR; against it gives +iR. Across an ideal source, − to + gives +ℰ. Loop and junction rules express energy and charge conservation.')
add(27,'Real battery and single-loop current',r'i=\frac{\mathcal{E}}{R+r}','27-4','R external resistance and r internal resistance (Ω); ℰ emf (V); i current (A).','One source and a single series loop. With r=0 the current is ℰ/R. A delivering battery’s terminal voltage is ℰ−ir; reversing current changes the sign of its internal drop.')
add(27,'Battery power',r'P=iV,\quad P_r=i^2r,\quad P_{\mathrm{emf}}=i\mathcal{E}','27-14,27-16,27-17','V battery terminal voltage (V); P terminal power, P_r internal heating, P_emf chemical conversion rate (W).','Use a stated current direction and source polarity. For a delivering battery, chemical power equals terminal power plus internal heating.')
add(27,'Equivalent resistance',r'R_{\mathrm{eq}}=\sum_{j=1}^{n}R_j\quad(\text{series}) ;; \frac1{R_{\mathrm{eq}}}=\sum_{j=1}^{n}\frac1{R_j}\quad(\text{parallel})','27-7,27-24','R_j,R_eq resistances (Ω).','Series resistors carry the same current; parallel resistors share the same voltage. Physical drawing position alone does not establish a series or parallel connection.')
add(27,'RC charging',r'q=C\mathcal{E}\left(1-e^{-t/(RC)}\right) ;; i=\frac{dq}{dt}=\frac{\mathcal{E}}{R}e^{-t/(RC)},\quad\tau=RC','27-33,27-34','q charge (C); C capacitance (F); R total series resistance (Ω); τ time constant (s).','Initially uncharged capacitor connected to a constant ideal source at t=0. Current starts at ℰ/R and tends to zero; capacitor voltage tends to ℰ.')
add(27,'RC discharging',r'q=q_0e^{-t/(RC)} ;; i=\frac{dq}{dt}=-\frac{q_0}{RC}e^{-t/(RC)}','27-39,27-40','q₀ initial plate charge (C); τ=RC (s); i referenced as dq/dt (A).','Source removed and capacitor discharging through R. The negative sign describes decreasing charge on the chosen initially positive plate; current magnitude is positive.')
add(28,'Magnetic force and field units',r'\vec F_B=q\vec v\times\vec B ;; 1\,\mathrm T=1\,\frac{\mathrm N}{\mathrm{A\,m}}=10^4\,\mathrm{gauss}','28-2','B magnetic field (T); q signed charge (C); v velocity (m/s); F_B force (N).','Magnetic force is perpendicular to velocity and does no work on a point charge. Reverse the right-hand-rule direction for negative charge. Hall-effect polarity identifies carrier sign.')
add(28,'Circular motion of a charge in a magnetic field',r'|q|vB=\frac{mv^2}{r},\quad r=\frac{mv}{|q|B} ;; f=\frac{\omega}{2\pi}=\frac1T=\frac{|q|B}{2\pi m}','28-15,28-16,28-17,28-18,28-19','r radius (m); f frequency (Hz); T period (s); m particle mass (kg).','Nonrelativistic motion in a uniform B with v perpendicular to B. For a helical path use the perpendicular velocity for the radius.')
add(28,'Force on a current-carrying wire',r'\vec F_B=i\vec L\times\vec B ;; d\vec F_B=i\,d\vec L\times\vec B','28-26,28-28','i current (A); L wire segment length vector (m); B field (T).','L points in the conventional-current direction. The finite straight-wire expression requires a uniform field; integrate the element form otherwise.')
add(28,'Magnetic dipole torque and orientation energy',r'\mu=NiA,\quad\vec\tau=\vec\mu\times\vec B ;; U=-\vec\mu\cdot\vec B ;; W_a=U_f-U_i','28-37,28-38,28-39','μ magnetic moment (A·m²); N turns; A loop area (m²); τ torque (N·m); U energy (J).','Uniform external B. Loop moment direction follows the current right-hand rule; W_a=ΔU assumes the dipole starts and ends with the same kinetic energy.')
add(29,'Biot–Savart law',r'd\vec B=\frac{\mu_0}{4\pi}\frac{i\,d\vec s\times\hat r}{r^2}','29-3','μ₀≈4π×10⁻⁷ T·m/A; i current (A); ds current-directed length element (m); r distance to observation point (m).','Steady currents in vacuum; r̂ points from the source element to the observation point. Integrate contributions as vectors.')
add(29,'Long wire, circular arc, and parallel-wire force',r'B=\frac{\mu_0i}{2\pi R} ;; B_{\mathrm{arc,center}}=\frac{\mu_0i\phi}{4\pi R} ;; F_{ba}=i_bLB_a=\frac{\mu_0Li_ai_b}{2\pi d}','29-4,29-9,29-13','R radius/perpendicular distance (m); φ arc angle (rad); i_a,i_b current magnitudes (A); d wire separation and L interacting length (m).','Long straight-wire approximation. Arc field is at its center; a complete circle has φ=2π. Parallel currents attract for the same direction and repel for opposite directions.')
add(29,'Ampère’s law and symmetric coils',r'\oint\vec B\cdot d\vec s=\mu_0i_{\mathrm{enc}} ;; B_{\mathrm{solenoid}}=\mu_0in ;; B_{\mathrm{toroid}}=\frac{\mu_0Ni}{2\pi r}','29-14,29-23,29-24','n turns per length (m⁻¹); N turns; r radius from toroid center (m); i_enc signed current piercing the loop (A).','Magnetostatics. Solenoid formula applies far from ends of a long coil; toroid formula applies inside an ideal densely wound toroid. Loop orientation fixes enclosed-current signs.')
add(29,'Far field of a magnetic dipole',r'\vec B(z)=\frac{\mu_0}{2\pi}\frac{\vec\mu}{z^3}','29-27','μ magnetic dipole moment (A·m²); z positive axial distance (m).','On the central axis far from a small current loop: z must greatly exceed the coil dimensions.')
add(30,'Magnetic flux and Faraday–Lenz law',r'\Phi_B=\int\vec B\cdot d\vec A,\quad\Phi_B=BA\quad(\vec B\text{ normal, uniform}) ;; \mathcal{E}=-\frac{d\Phi_B}{dt},\quad\mathcal{E}=-N\frac{d\Phi_B}{dt}','30-1,30-2,30-4,30-5','Φ_B magnetic flux (Wb=T·m²); ℰ induced emf (V); A area (m²); N identical linked turns.','Use the same area orientation and loop direction. The minus sign gives opposition to the change of flux, not necessarily to the original magnetic field.')
add(30,'Induced electric field',r'\mathcal{E}=\oint\vec E\cdot d\vec s ;; \oint\vec E\cdot d\vec s=-\frac{d\Phi_B}{dt}','30-19,30-20','E induced electric field (V/m); ds oriented loop element (m).','Changing magnetic flux creates a circulating nonconservative electric field even without a physical conducting loop.')
add(30,'Inductance and self-induction',r'L=\frac{N\Phi_B}{i} ;; \frac L\ell=\mu_0n^2A ;; \mathcal{E}_L=-L\frac{di}{dt}','30-28,30-31,30-35','L inductance (H=Wb/A); ℓ solenoid length (m); n turns per meter; A area (m²).','Constant linear inductance; ideal long air-core solenoid for L/ℓ. The induced emf opposes a change of current.')
add(30,'RL current growth and decay',r'i=\frac{\mathcal{E}}{R}\left(1-e^{-t/\tau_L}\right),\quad\tau_L=\frac LR ;; i=i_0e^{-t/\tau_L}','30-41,30-45','i current (A); τ_L inductive time constant (s); R total loop resistance (Ω).','Growth starts from zero current under a constant source; decay starts from i₀ after the source is removed with a closed R–L path remaining.')
add(30,'Stored magnetic energy and mutual induction',r'U_B=\frac12Li^2,\quad u_B=\frac{B^2}{2\mu_0} ;; \mathcal{E}_2=-M\frac{di_1}{dt},\quad\mathcal{E}_1=-M\frac{di_2}{dt}','30-49,30-55,30-64,30-65','U_B energy (J); u_B energy density (J/m³); M mutual inductance (H).','Energy-density formula is for vacuum. Mutual-emf signs require consistent coil orientation; the displayed negative sign uses the chapter’s compatible reference directions.')
add(31,'Ideal LC oscillation',r'U_E=\frac{q^2}{2C},\quad U_B=\frac12Li^2 ;; L\frac{d^2q}{dt^2}+\frac qC=0,\quad\omega=\frac1{\sqrt{LC}} ;; q=Q\cos(\omega t+\phi),\quad i=-\omega Q\sin(\omega t+\phi)','31-1,31-2,31-4,31-11,31-12,31-13','Q charge amplitude (C); q instantaneous charge (C); i=dq/dt (A); L inductance (H); C capacitance (F).','No resistance or external drive. Total electric plus magnetic energy stays constant; current and charge are π/2 out of phase.')
add(31,'Damped RLC oscillation',r'L\frac{d^2q}{dt^2}+R\frac{dq}{dt}+\frac qC=0 ;; q=Qe^{-Rt/(2L)}\cos(\omega^{\prime}t+\phi) ;; \omega^{\prime}=\sqrt{\omega^2-\left(\frac R{2L}\right)^2}','31-24,31-25,31-26','R resistance (Ω); ω=1/√(LC) and ω′ damped angular frequency (rad/s).','Series RLC free response. The oscillatory solution requires underdamping; the chapter emphasizes small R so ω′≈ω.')
add(31,'AC drive, reactances, and element phases',r'\mathcal{E}=\mathcal{E}_m\sin(\omega_dt),\quad i=I\sin(\omega_dt-\phi) ;; V_R=IR,\quad X_C=\frac1{\omega_dC},\quad V_C=IX_C ;; X_L=\omega_dL,\quad V_L=IX_L','31-28,31-29','ℰ_m,I,V_R,V_C,V_L peak amplitudes (V or A); X reactance (Ω); ω_d drive frequency (rad/s).','For a pure resistor current is in phase; for a capacitor it leads voltage by 90°; for an inductor it lags by 90°. Do not mix peak and RMS quantities.')
add(31,'Series RLC impedance and resonance',r'Z=\sqrt{R^2+(X_L-X_C)^2} ;; I=\frac{\mathcal{E}_m}{Z}=\frac{\mathcal{E}_m}{\sqrt{R^2+(\omega_dL-1/(\omega_dC))^2}} ;; \tan\phi=\frac{X_L-X_C}{R} ;; \omega_d=\frac1{\sqrt{LC}}\Rightarrow X_L=X_C,\quad I=\frac{\mathcal{E}_m}{R}','31-60,31-61,31-63,31-65','Z impedance magnitude (Ω); φ lag of current behind the source voltage (rad); I peak current (A).','Sinusoidal steady state in a series circuit with R>0. Positive φ is inductive lag; negative φ is capacitive lead. At resonance φ=0 and current amplitude is maximal.')
add(31,'RMS values and average AC power',r'I_{\mathrm{rms}}=\frac I{\sqrt2},\quad V_{\mathrm{rms}}=\frac V{\sqrt2},\quad\mathcal{E}_{\mathrm{rms}}=\frac{\mathcal{E}_m}{\sqrt2} ;; P_{\mathrm{avg}}=I_{\mathrm{rms}}^2R=\mathcal{E}_{\mathrm{rms}}I_{\mathrm{rms}}\cos\phi','31-71,31-76','P_avg real power (W); cosφ power factor (dimensionless).','Peak/√2 conversion assumes sinusoids. Ideal inductors and capacitors exchange energy but absorb zero average real power.')
add(31,'Ideal transformer',r'V_s=V_p\frac{N_s}{N_p},\quad I_s=I_p\frac{N_p}{N_s} ;; R_{\mathrm{eq}}=\left(\frac{N_p}{N_s}\right)^2R','31-79,31-80,31-82','N_p,N_s primary/secondary turns; V voltages; I currents; R secondary resistive load (Ω).','Ideal lossless AC transformer with tight magnetic coupling. Use the same amplitude convention on both sides; input and output real powers match.')
add(32,'Magnetic Gauss law and Ampère–Maxwell law',r'\oint_S\vec B\cdot d\vec A=0 ;; \oint\vec B\cdot d\vec s=\mu_0\epsilon_0\frac{d\Phi_E}{dt}\quad(i_{\mathrm{enc}}=0) ;; \oint\vec B\cdot d\vec s=\mu_0i_{\mathrm{enc}}\quad(\text{steady fields}) ;; \oint\vec B\cdot d\vec s=\mu_0i_{\mathrm{enc}}+\mu_0\epsilon_0\frac{d\Phi_E}{dt}','32-1,32-3,32-4,32-5','Φ_E electric flux (V·m); i_enc conduction current (A); B field (T).','Use oriented closed surfaces for Gauss and oriented closed paths for circulation. The displacement term is essential in time-varying fields, including a charging capacitor.')
add(32,'Displacement current',r'i_d=\epsilon_0\frac{d\Phi_E}{dt} ;; \oint\vec B\cdot d\vec s=\mu_0(i_{\mathrm{enc}}+i_{d,\mathrm{enc}})','32-10,32-11','i_d displacement current (A); Φ_E electric flux through the chosen spanning surface.','Displacement current describes changing electric flux; it is not charge flowing through the insulating gap.')
add(32,'Electron spin and Bohr magneton',r'\vec\mu_s=-\frac em\vec S ;; S_z=m_s\hbar,\quad m_s=\pm\frac12 ;; \mu_B=\frac{e\hbar}{2m}=\frac{eh}{4\pi m}\approx9.27\times10^{-24}\,\mathrm{J/T} ;; \mu_{s,z}=-2m_s\mu_B=\pm\mu_B ;; U=-\vec\mu_s\cdot\vec B_{\mathrm{ext}}=-\mu_{s,z}B_{\mathrm{ext}}','32-22,32-23,32-24,32-25,32-26,32-27','e positive elementary-charge magnitude (C); m electron mass (kg); ℏ=h/(2π) (J·s); μ moment (J/T=A·m²).','Book’s approximate electron spin magnetic factor g≈2. Electron magnetic moment is opposite its spin; take z along the external field for the scalar energy.')
add(32,'Orbital magnetic moment',r'\vec\mu_{\mathrm{orb}}=-\frac e{2m}\vec L_{\mathrm{orb}} ;; L_{\mathrm{orb},z}=m_\ell\hbar ;; \mu_{\mathrm{orb},z}=-m_\ell\mu_B ;; U=-\vec\mu_{\mathrm{orb}}\cdot\vec B_{\mathrm{ext}}=-\mu_{\mathrm{orb},z}B_{\mathrm{ext}}','32-28,32-29,32-30,32-31,32-32','m_ℓ orbital magnetic quantum number (integer); L angular momentum (J·s); μ magnetic moment (J/T).','Allowed m_ℓ values depend on the orbital quantum number. These are measured projections, not arbitrary classical orbit orientations.')
add(32,'Magnetization and Curie’s law',r'M=\frac{\text{net magnetic moment}}{V},\quad M_{\max}=\frac{N\mu}{V} ;; M=C\frac{B_{\mathrm{ext}}}{T}','32-38,32-39','M magnetization (A/m); N number of dipoles; V sample volume (m³); T temperature (K); C material Curie constant.','Curie’s law is a low-B/T paramagnetic approximation before saturation. It does not describe ferromagnetic hysteresis or all magnetic materials.')
add(33,'Electromagnetic-wave fields and speed',r'E=E_m\sin(kx-\omega t),\quad B=B_m\sin(kx-\omega t) ;; c=\frac EB=\frac1{\sqrt{\mu_0\epsilon_0}}','33-1,33-2,33-3,33-5','E field (V/m); B field (T); c vacuum light speed (m/s); k rad/m; ω rad/s.','Plane traveling wave in vacuum. E and B are in phase, perpendicular to each other and to propagation; use E/B away from their simultaneous zero crossings.')
add(33,'Poynting vector and intensity',r'\vec S=\frac1{\mu_0}\vec E\times\vec B ;; I=\frac{E_{\mathrm{rms}}^2}{c\mu_0},\quad E_{\mathrm{rms}}=\frac{E_m}{\sqrt2} ;; I=\frac{P_s}{4\pi r^2}','33-19,33-26,33-27','S instantaneous energy flux and I mean intensity (W/m²); P_s emitted power (W); r distance (m).','Vacuum plane-wave relation; RMS expression assumes a sinusoid. Inverse-square spreading requires an isotropic point source without losses.')
add(33,'Radiation force and pressure',r'F=\frac{IA}{c},\quad p_r=\frac Ic\quad(\text{absorption}) ;; F=\frac{2IA}{c},\quad p_r=\frac{2I}{c}\quad(\text{back reflection})','33-32,33-33,33-34,33-35','F force (N); p_r pressure (Pa); A illuminated perpendicular area (m²).','Normal incidence with complete absorption or perfect reversal along the incoming path. Partial reflection or oblique incidence needs a momentum balance.')
add(33,'Polarizers',r'I=\frac12I_0\quad(\text{unpolarized input}) ;; I=I_0\cos^2\theta\quad(\text{polarized input})','33-36,33-38','I intensity (W/m²); θ angle between incident polarization and analyzer axis.','Ideal linear polarizer. After the first polarizer the beam is polarized, so apply Malus’s law for each subsequent sheet.')
add(33,'Reflection, Snell’s law, and special angles',r'\theta_r=\theta_i,\quad n_2\sin\theta_2=n_1\sin\theta_1 ;; \theta_c=\sin^{-1}\frac{n_2}{n_1}\quad(n_1>n_2) ;; \theta_B=\tan^{-1}\frac{n_2}{n_1}','33-40,33-45,33-49','n refractive index (dimensionless); angles measured from the surface normal.','Total internal reflection requires light going from higher to lower index and incidence above θ_c. Brewster reflection is fully polarized perpendicular to the incidence plane for ordinary transparent nonmagnetic media.')
add(34,'Spherical and plane mirrors',r'\frac1p+\frac1i=\frac1f=\frac2r ;; p=-i\quad(\text{plane mirror})','34-3,34-4','p object distance, i image distance, f focal length, r curvature radius (m).','Paraxial rays near the central axis. For a real object p>0; real image i>0 and virtual image i<0. Concave mirror has positive f; convex mirror negative f.')
add(34,'Refraction at one spherical surface',r'\frac{n_1}{p}+\frac{n_2}{i}=\frac{n_2-n_1}{r}','34-8','n₁ object-side and n₂ image-side refractive index; p,i,r distances (m).','Single spherical refracting interface and paraxial rays. Use the book’s sign convention: a surface convex toward the object has r>0; real refracted images have i>0.')
add(34,'Thin lens and lensmaker relation',r'\frac1p+\frac1i=\frac1f ;; \frac1f=(n-1)\left(\frac1{r_1}-\frac1{r_2}\right)','34-9,34-10','n lens refractive index relative to surrounding air; r₁,r₂ signed surface radii (m).','Thin lens, paraxial rays, lens in air. A standard biconvex lens has r₁>0,r₂<0 with light traveling from the first to the second surface; use signed radii, not two positive magnitudes.')
add(34,'Lateral magnification',r'm=-\frac ip,\quad |m|=\frac{h^{\prime}}h','34-5,34-6','m dimensionless magnification; h,h′ nonnegative object/image heights (m); p,i signed distances (m).','For a thin lens or mirror under this chapter’s convention: m<0 means inverted; m>0 upright. The displayed height ratio gives magnitude.')
add(34,'Magnifier, microscope, and telescope',r'm_\theta=\frac{25\,\mathrm{cm}}f ;; M=mm_\theta\approx-\frac{s}{f_{\mathrm{ob}}}\frac{25\,\mathrm{cm}}{f_{\mathrm{ey}}} ;; m_{\theta,\mathrm{telescope}}=-\frac{f_{\mathrm{ob}}}{f_{\mathrm{ey}}}','34-12,34-14,34-15','f focal length; s microscope tube length; f_ob objective and f_ey eyepiece focal lengths, all in one length unit.','Relaxed-eye viewing with final image at infinity, using the book’s 25 cm reference near-point distance. Microscope relation uses the long-tube approximation; negative sign indicates inversion.')
add(35,'Wavelength in a medium',r'n=\frac cv,\quad\lambda_n=\frac\lambda n','35-6','n refractive index; λ vacuum wavelength and λ_n medium wavelength (m); c,v speeds (m/s).','Frequency stays unchanged across a stationary boundary; phase accumulates according to the wavelength inside each material.')
add(35,'Young’s double-slit fringes and intensity',r'd\sin\theta=m\lambda\quad(\text{bright}) ;; d\sin\theta=(m+\tfrac12)\lambda\quad(\text{dark}) ;; I=4I_0\cos^2\frac\phi2,\quad\phi=\frac{2\pi d}{\lambda}\sin\theta','35-14,35-16,35-22,35-23','d slit separation (m); θ viewing angle; I₀ intensity from each slit (W/m²); m integer fringe order.','Coherent equal-intensity sources initially in phase; far-field path difference d sinθ. Add an initial phase offset when one is present.')
add(35,'Reflected thin-film interference',r'2L=(m+\tfrac12)\frac\lambda{n_2}\quad(\text{bright}) ;; 2L=m\frac\lambda{n_2}\quad(\text{dark})','35-36,35-37','L film thickness (m); n₂ film index; λ wavelength in air (m); m=0,1,2,… .','Near-normal incidence on a film in air with exactly one reflection phase reversal. Recheck both interface phase shifts for a film on a substrate; zero or two reversals interchange bright/dark conditions.')
add(35,'Reflection phase and interferometer path',r'\Delta\phi_{\mathrm{reflection}}=\pi\quad(n_{\mathrm{incident}}<n_{\mathrm{transmitted}}) ;; \Delta\phi_{\mathrm{reflection}}=0\quad(n_{\mathrm{incident}}>n_{\mathrm{transmitted}})','','Phase shift is in radians. Optical path length uses refractive index times geometric length.','For ordinary transparent interfaces. A Michelson interferometer compares the round-trip optical paths of its arms; count both outward and return travel when a mirror moves.')
add(36,'Single-slit diffraction',r'a\sin\theta=m\lambda,\quad m=1,2,3,\ldots\quad(\text{minima}) ;; I(\theta)=I_m\left(\frac{\sin\alpha}{\alpha}\right)^2,\quad\alpha=\frac{\pi a}{\lambda}\sin\theta','36-3,36-5,36-6','a slit width (m); I_m central intensity (W/m²); λ wavelength (m).','Far-field diffraction by a uniformly illuminated narrow slit. m=0 is the central maximum, not a minimum. At α=0 use the limit sinα/α=1.')
add(36,'Circular aperture and Rayleigh resolution',r'\sin\theta_{\min}=1.22\frac\lambda d ;; \theta_R\approx1.22\frac\lambda d','36-12,36-14','d aperture diameter (m); θ_R angular separation (rad).','Circular unobstructed aperture. Rayleigh’s angular form uses the small-angle approximation; one source’s central maximum lies at the other’s first minimum.')
add(36,'Two slits with finite width',r'I(\theta)=I_m\cos^2\beta\left(\frac{\sin\alpha}{\alpha}\right)^2 ;; \beta=\frac{\pi d}{\lambda}\sin\theta,\quad\alpha=\frac{\pi a}{\lambda}\sin\theta','36-19','d center separation and a width of each slit (m); α,β dimensionless phase parameters.','Coherent far-field illumination. The interference factor is modulated by the single-slit diffraction envelope; some bright orders can be missing.')
add(36,'Diffraction grating: orders, widths, and resolution',r'd\sin\theta=m\lambda ;; \Delta\theta_{\mathrm{hw}}\approx\frac\lambda{Nd\cos\theta} ;; D=\frac{\Delta\theta}{\Delta\lambda}=\frac m{d\cos\theta} ;; \mathcal{R}=\frac{\lambda_{\mathrm{avg}}}{\Delta\lambda}=Nm','36-25,36-28,36-29,36-30,36-31,36-32','N illuminated slits; d spacing (m); m diffraction order; D dispersion (rad/m); ℛ dimensionless resolving power.','Ideal regularly spaced grating; physical orders require |mλ/d|≤1. The half-width is from a principal maximum to its first adjacent minimum, not a full width.')
add(36,'Bragg diffraction',r'2d\sin\theta=m\lambda,\quad m=1,2,3,\ldots','36-34','d crystal-plane spacing (m); θ glancing angle measured from the crystal planes.','Constructive reflection from successive parallel lattice planes. θ is not measured from the plane normal.')
add(37,'Lorentz factor, time dilation, and length contraction',r'\beta=\frac vc,\quad\gamma=\frac1{\sqrt{1-\beta^2}} ;; \Delta t=\gamma\Delta t_0 ;; L=\frac{L_0}{\gamma}=L_0\sqrt{1-\beta^2}','37-7,37-8,37-9,37-13','v relative frame speed (m/s); Δt₀ proper time (s); L₀ proper length (m).','Inertial frames. Proper time is measured where both events occur at one position. Length contraction affects the direction of relative motion; moving-frame endpoint positions must be measured simultaneously there.')
add(37,'Lorentz transformation and collinear velocity addition',r'x^{\prime}=\gamma(x-vt),\quad y^{\prime}=y,\quad z^{\prime}=z ;; t^{\prime}=\gamma\left(t-\frac{vx}{c^2}\right) ;; u=\frac{u^{\prime}+v}{1+u^{\prime}v/c^2}','37-21,37-29','x,y,z event positions (m); t event time (s); v speed of S′ in the +x direction relative to S.','Parallel axes with coincident origins at t=t′=0. The velocity formula is collinear; retain signs for objects moving in the opposite direction.')
add(37,'Relativistic Doppler shifts',r'\lambda=\lambda_0\sqrt{\frac{1+\beta}{1-\beta}}\quad(\text{separating}) ;; v\approx\frac{|\Delta\lambda|}{\lambda_0}c\quad(v\ll c) ;; f=f_0\sqrt{1-\beta^2}\quad(\text{transverse})','37-32,37-36,37-37','λ₀ rest-frame source wavelength (m); f₀ source proper frequency (Hz); β=v/c.','For direct approach, reverse the β signs in the wavelength ratio. The speed approximation gives a magnitude. The transverse relation uses the chapter’s perpendicular observation geometry.')
add(37,'Relativistic momentum, energy, and mass conversion',r'\vec p=\gamma m\vec v ;; E=mc^2+K=\gamma mc^2,\quad K=(\gamma-1)mc^2 ;; (pc)^2=K^2+2Kmc^2 ;; E^2=(pc)^2+(mc^2)^2 ;; Q=(M_i-M_f)c^2=-\Delta Mc^2','37-42,37-47,37-48,37-50,37-52,37-54,37-55','m invariant mass (kg); E total and K kinetic energy (J); p momentum (kg·m/s); Q released energy (J).','Use the Lorentz factor of the particle in the chosen frame. Positive Q means initial rest mass exceeds final rest mass; total energy and momentum still conserve.')
add(38,'Photon energy, momentum, and photoelectric effect',r'E=hf,\quad p=\frac{hf}{c}=\frac h\lambda ;; hf=K_{\max}+\Phi','38-2,38-5,38-7','h Planck constant (J·s); f frequency (Hz); λ vacuum wavelength (m); Φ work function (J or eV consistently).','A photon transfers a quantum of energy. Emission requires hf≥Φ; increasing intensity at fixed frequency does not increase maximum photoelectron kinetic energy.')
add(38,'Compton wavelength shift',r'\Delta\lambda=\frac h{mc}(1-\cos\phi)','38-11','m electron mass (kg); φ photon scattering angle; h/(mc) Compton wavelength (m).','Photon scattering from an initially stationary effectively free electron. φ is the angle of the outgoing photon relative to the incoming one.')
add(38,'Blackbody spectrum and Wien peak',r'S(\lambda)=\frac{2\pi hc^2}{\lambda^5}\frac1{e^{hc/(\lambda kT)}-1} ;; \lambda_{\max}T=2898\,\mathrm{\mu m\,K}=2.898\times10^{-3}\,\mathrm{m\,K}','38-14,38-15','S(λ) spectral emitted power per area per wavelength (W/m³); λ wavelength (m); T temperature (K).','Ideal blackbody. This is the book’s wavelength spectral radiancy integrated over emission directions; a spectrum per unit frequency has a different peak location.')
add(38,'Matter waves and stationary Schrödinger equation',r'\lambda=\frac hp ;; \Psi(x,t)=\psi(x)e^{-i\omega t} ;; \frac{d^2\psi}{dx^2}+\frac{8\pi^2m}{h^2}[E-U(x)]\psi=0','38-19','p momentum (kg·m/s); m mass (kg); E total and U potential energy (J); |ψ|² probability density.','One-dimensional nonrelativistic particle in a time-independent potential. For a free particle U=0. Use relativistic momentum for de Broglie wavelength when speed is high.')
add(38,'Position–momentum uncertainty: the book’s convention',r'\Delta x\,\Delta p_x\ge\hbar ;; \Delta y\,\Delta p_y\ge\hbar ;; \Delta z\,\Delta p_z\ge\hbar','38-28','ℏ=h/(2π) (J·s); Δx spatial uncertainty (m); Δp momentum uncertainty (kg·m/s).','These reproduce the chapter’s uncertainty-width convention and are used as uncertainty-scale estimates. Do not identify these widths with a sharp standard-deviation inequality; that convention has the bound ℏ/2.')
add(38,'Potential step and barrier tunneling',r'T=1-R ;; T\approx e^{-2bL},\quad b=\sqrt{\frac{8\pi^2m(U_b-E)}{h^2}}','38-38,38-39','T transmission and R reflection probability (dimensionless); L barrier width (m); U_b barrier height and E particle energy (J); b decay constant (m⁻¹).','Conservative single-channel scattering gives T+R=1. The exponential is an opaque rectangular-barrier approximation for E<U_b; it omits prefactors and is not an exact thin-barrier transmission formula.')
add(39,'One-dimensional infinite well',r'E_n=\frac{h^2n^2}{8mL^2},\quad n=1,2,3,\ldots ;; \psi_n(x)=\sqrt{\frac2L}\sin\frac{n\pi x}{L} ;; \int_{-\infty}^{\infty}|\psi_n(x)|^2\,dx=1','39-4,39-10,39-14','L well width (m); m particle mass (kg); E_n energy (J); ψ has units m⁻¹/² in 1D.','Infinite walls at x=0,L; wavefunction is zero outside. Ground state n=1 has nonzero energy. Detection probability in dx is |ψ|²dx.')
add(39,'Energy jumps and photons',r'\Delta E=E_{\mathrm{high}}-E_{\mathrm{low}}=hf=\frac{hc}{\lambda}','39-5,39-6','ΔE positive transition energy (J); f photon frequency (Hz); λ wavelength (m).','Absorption raises the particle’s energy; emission lowers it by the same photon energy. Use one energy unit consistently.')
add(39,'Two-dimensional rectangular well',r'E_{n_x,n_y}=\frac{h^2}{8m}\left(\frac{n_x^2}{L_x^2}+\frac{n_y^2}{L_y^2}\right) ;; \psi_{n_x,n_y}=\sqrt{\frac2{L_x}}\sin\frac{n_x\pi x}{L_x}\sqrt{\frac2{L_y}}\sin\frac{n_y\pi y}{L_y}','39-19,39-20','Lₓ,Lᵧ side lengths (m); nₓ,nᵧ independently positive integers.','Infinite rectangular walls with separable coordinates. Different quantum-number pairs can share an energy (degeneracy).')
add(39,'Bohr angular momentum: historical rule',r'L_{\mathrm{Bohr}}=n\hbar,\quad n=1,2,3,\ldots','39-23','L_Bohr model angular momentum (J·s); n principal quantum number.','Historical model relation, explicitly identified as incorrect in the summary. Do not use it as the quantum-mechanical orbital angular momentum; Chapter 40 gives √[ℓ(ℓ+1)]ℏ.')
add(39,'Hydrogen levels and spectral wavelengths',r'E_n=-\frac{me^4}{8\epsilon_0^2h^2n^2}=-\frac{13.60\,\mathrm{eV}}{n^2} ;; \frac1\lambda=R\left(\frac1{n_{\mathrm{low}}^2}-\frac1{n_{\mathrm{high}}^2}\right) ;; R=\frac{me^4}{8\epsilon_0^2h^3c}\approx1.097373\times10^7\,\mathrm{m^{-1}}','39-34,39-37,39-38','m electron mass; n positive integer; R Rydberg constant (m⁻¹); λ wavelength (m).','Nonrelativistic hydrogen with the chapter’s fixed-proton approximation; n_high>n_low. E=0 is the ionized electron at infinite separation; precision values require reduced-mass and other corrections.')
add(39,'Radial detection probability',r'\Pr(r_1<r<r_2)=\int_{r_1}^{r_2}P(r)\,dr','39-45','P(r) radial probability density (m⁻¹); r radial distance from nucleus (m).','P(r) already includes the radial volume weighting after angular integration; do not multiply it by 4πr² a second time.')
add(40,'Atomic transition energies',r'hf=E_{\mathrm{high}}-E_{\mathrm{low}}','40-1','f emitted/absorbed photon frequency (Hz); h Planck constant (J·s); energies in joules.','Electronic levels are quantized. States sharing n form a shell; sharing n and ℓ forms a subshell.')
add(40,'Orbital angular momentum and moment',r'L=\sqrt{\ell(\ell+1)}\hbar,\quad\ell=0,1,\ldots,n-1 ;; L_z=m_\ell\hbar,\quad m_\ell=-\ell,\ldots,+\ell ;; \mu_{\mathrm{orb}}=\frac e{2m}\sqrt{\ell(\ell+1)}\hbar ;; \mu_{\mathrm{orb},z}=-m_\ell\mu_B,\quad\mu_B=\frac{e\hbar}{2m}\approx9.274\times10^{-24}\,\mathrm{J/T}','40-2,40-3,40-6,40-7,40-8','ℓ orbital and m_ℓ magnetic quantum numbers; m electron mass (kg); e positive elementary-charge magnitude (C).','Measured projections are quantized. Electron moment points opposite orbital angular momentum; magnitude and z component are different quantities.')
add(40,'Electron spin and spin moment',r'S=\sqrt{s(s+1)}\hbar,\quad s=\frac12 ;; S_z=m_s\hbar,\quad m_s=\pm\frac12 ;; \mu_s=\frac em\sqrt{s(s+1)}\hbar ;; \mu_{s,z}=-2m_s\mu_B','40-9,40-10,40-12,40-13','S spin angular momentum (J·s); μ_s moment magnitude (J/T); m_s spin projection quantum number.','Approximate electron g-factor 2 as used in the chapter. Pauli exclusion prevents two electrons in the same trap from sharing all quantum numbers.')
add(40,'Magnetic gradient force and proton resonance',r'F_z=\mu_z\frac{dB}{dz} ;; hf=2\mu_zB','40-17,40-22','μ_z dipole projection (J/T); dB/dz field gradient (T/m); F_z force (N); f spin-flip frequency (Hz).','Gradient-force form assumes a fixed dipole projection and dominant axial field variation. For the proton spin-flip gap use the positive projection magnitude and the local total field, including its environment.')
add(40,'X-ray cutoff',r'\lambda_{\min}=\frac{hc}{K_0}','','K₀ incident electron kinetic energy (J); λ_min shortest emitted wavelength (m).','An electron gives all its kinetic energy to one bremsstrahlung photon. Characteristic x-ray lines arise instead from discrete atomic level transitions.')
add(41,'Counting conduction electrons',r'N_{\mathrm{cond}}=N_{\mathrm{atoms}}z_v,\quad n=\frac{N_{\mathrm{cond}}}{V} ;; N_{\mathrm{atoms}}=\frac{M_{\mathrm{sam}}}{M/N_A}=\frac{\rho V N_A}{M}','41-2,41-3,41-4','z_v contributing valence electrons per atom; n number density (m⁻³); M molar mass (kg/mol); ρ density (kg/m³).','Free-electron metal model. Use the assumed number of conducting electrons per atom, not automatically the total number of atomic electrons.')
add(41,'Density of states and Fermi occupation',r'N(E)=\frac{8\sqrt2\pi m^{3/2}}{h^3}E^{1/2} ;; P(E)=\frac1{e^{(E-E_F)/(kT)}+1} ;; N_o(E)=N(E)P(E)','41-5,41-6,41-7','N(E) states per volume per energy (m⁻³ J⁻¹); P(E) occupation probability; m electron mass (kg); E,E_F energy (J).','Three-dimensional free-electron density of states with spin included. Keep energy in joules; switching both E and density units to eV requires the corresponding conversion, not substitution of a numerical eV value into the SI formula.')
add(41,'Fermi energy',r'E_F=\frac{\hbar^2}{2m}(3\pi^2n)^{2/3}\approx\frac{0.121h^2}{m}n^{2/3}','41-9','n conduction electron density (m⁻³); E_F energy at the highest occupied level at 0 K (J).','Noninteracting 3D electron-gas approximation. The equivalent ℏ form preserves the full coefficient instead of rounding it.')
add(41,'Semiconductor photon wavelength',r'\lambda=\frac cf=\frac{hc}{E_g}','41-11','E_g semiconductor energy gap (J); λ emitted wavelength (m).','Approximate band-edge photon energy for the chapter’s LED model. Use consistent energy units; actual device spectra depend on material and transitions.')
add(42,'Nuclide counts, radius, and mass excess',r'A=Z+N ;; r=r_0A^{1/3},\quad r_0\approx1.2\,\mathrm{fm} ;; \Delta=M-A','42-3,42-6','A mass number; Z proton count; N neutron count; r nuclear radius (m); M atomic mass expressed numerically in u; Δ mass excess (u).','The radius law is an empirical nuclear scale. In Δ=M−A, subtract A atomic mass units; this is mass excess, not the binding-energy mass defect.')
add(42,'Binding energy and mass–energy conversion',r'\Delta E_{\mathrm{be}}=\sum mc^2-Mc^2 ;; \Delta E_{\mathrm{ben}}=\frac{\Delta E_{\mathrm{be}}}{A} ;; 1\,\mathrm u\,c^2\approx931.494013\,\mathrm{MeV}','42-7,42-8','ΔE_be total binding energy; ΔE_ben energy per nucleon; masses must describe a consistent set of constituents.','Use nuclear masses with proton/neutron masses, or neutral-atom masses with hydrogen-atom masses so electrons cancel. Do not mix atomic and bare nuclear masses without accounting for electrons.')
add(42,'Radioactive decay, activity, and half-life',r'N=N_0e^{-\lambda t} ;; R=-\frac{dN}{dt}=\lambda N=R_0e^{-\lambda t} ;; T_{1/2}=\frac{\ln2}{\lambda}','42-15,42-16,42-17','N undecayed parent count; λ decay constant (s⁻¹); R activity (Bq=s⁻¹); T₁/₂ half-life (s).','Independent decay with a constant decay probability. Daughter production and decay chains require additional balances; one exponential is not a whole-chain solution.')
add(42,'Decay energy and radiation units',r'Q=-\Delta mc^2,\quad K_{\max,\beta}\approx Q ;; 1\,\mathrm{Bq}=1\,\mathrm{s^{-1}},\quad1\,\mathrm{Gy}=1\,\mathrm{J/kg}','','Q available decay energy (J or MeV); Gy absorbed dose; Sv dose equivalent with biological weighting.','In beta decay the electron/positron shares energy with a neutrino and recoil, giving a continuous spectrum. Activity and absorbed dose measure different things; sieverts also depend on radiation/tissue weighting.')
add(43,'Fission energy scale',r'Q\approx200\,\mathrm{MeV}\quad(\text{one typical }{}^{235}\mathrm U\text{ fission})','','Q energy per fission event; 1 eV≈1.602×10⁻¹⁹ J.','The chapter’s rounded thermal-neutron-induced uranium-235 fission scale, not a universal energy for every fission channel. Product masses determine the actual Q value.')
add(43,'Lawson confinement benchmark',r'n\tau>10^{20}\,\mathrm{s/m^3}','43-16','n plasma particle number density (m⁻³); τ confinement time (s); T plasma temperature (K or energy-equivalent temperature as specified).','The chapter’s approximate fusion benchmark also requires a suitable temperature. The numerical threshold depends on fuel, temperature, energy losses, and the definition of confinement time; it is not sufficient by itself.')
add(44,'Lepton and quark quantum-number bookkeeping',r'q_{e,\mu,\tau}=-e,\quad q_{\nu}=0 ;; q_{u,c,t}=+\frac23e,\quad q_{d,s,b}=-\frac13e ;; B_q=\frac13,\quad B_{\bar q}=-\frac13 ;; S_s=-1,\quad S_{\bar s}=+1','','q electric charge (C); B baryon number and S strangeness (dimensionless).','Antiparticle additive quantum numbers reverse sign. Sum constituent charges and baryon numbers to check a proposed hadron; strangeness is not conserved in every weak process.')
add(44,'Hubble relation and the book’s numerical value',r'v=Hr ;; H=71.0\,\mathrm{km\,s^{-1}\,Mpc^{-1}}\approx21.8\,\mathrm{mm\,s^{-1}\,ly^{-1}}','44-19,44-21','v recession speed (m/s); r distance (m); H expansion-rate parameter (s⁻¹ after converting distances consistently).','Use the H supplied by your problem. The quoted 71.0 value is this edition’s textbook value, not a claim about the latest cosmological measurement. The simple linear speed–distance use is local/low-redshift.')

def build():
 import hashlib, subprocess, xml.etree.ElementTree as ET
 try:
  import latex2mathml.converter
 except ImportError:
  raise SystemExit('Install the pinned latex2mathml build dependency; see README.md.')
 raw=(ROOT/'site/book-data.js').read_text();books=json.loads(raw[raw.index('['):].rstrip(';\n'))
 book=next(b for b in books if b['id']=='physics');offset=book['printedOffset']
 output=[];audit=[];missing=[];total=0;eqcount=0
 for g in book['groups']:
  c=g['number']
  if not isinstance(c,int) or not 1<=c<=44:continue
  sections=g['sections'];summary=next(s for s in sections if 'REVIEW' in s['title'].upper());stop=sections[sections.index(summary)+1]
  path=ROOT/'site'/g['file'];rawtext=subprocess.check_output(['pdftotext','-layout',str(path),'-']).decode();pages=rawtext.split('\f')
  source='\n'.join(pages[summary['localPage']-1:stop['localPage']]);m=re.search(r'^\s*Review & Summary\s*$',source,re.M);assert m,f'Missing summary heading {c}'
  source=source[m.end():];end=re.search(r'^\s*(?:Questions|Problems)\b',source,re.M)
  if end:source=source[:end.start()]
  found=set()
  for match in re.finditer(r'\((\d{1,2}-\d{1,3}(?:\s*(?:,|to)\s*\d{1,2}-\d{1,3})*)\)',source):
   text=match[1];refs=re.findall(r'\d{1,2}-\d{1,3}',text)
   if 'to' in text and len(refs)==2:
    a,b=refs;ca,ia=map(int,a.split('-'));cb,ib=map(int,b.split('-'));assert ca==cb;found.update(f'{ca}-{i}' for i in range(ia,ib+1))
   else:found.update(refs)
  used=set();groups=[]
  for i,e in enumerate(chapters[c],1):
   used.update(e['references']);sourcepages=set()
   for ref in e['references']:
    matches=[j+1 for j in range(summary['localPage']-1,stop['localPage']) if ref in pages[j]]
    if not matches and ref in found:
     for j in range(summary['localPage']-1,stop['localPage']):
      for match in re.finditer(r'(\d{1,2})-(\d{1,3})\s+to\s+(\d{1,2})-(\d{1,3})',pages[j]):
       ca,a,cb,b=map(int,match.groups());cr,ir=map(int,ref.split('-'))
       if ca==cb==cr and a<=ir<=b:matches.append(j+1)
    assert matches,f'Equation {ref} not found on summary pages for chapter {c}'
    sourcepages.add(g['start']+matches[0]-1)
   if not sourcepages:sourcepages.add(summary['pdfPage'])
   mathml=[]
   for tex in e['tex']:
    rendered=latex2mathml.converter.convert(tex,display='block');ET.fromstring(rendered);assert '<merror' not in rendered;mathml.append(rendered);eqcount+=1
   groups.append(dict(id=f'physics-{c}-{i}',**e,mathml=mathml,sourcePages=sorted(sourcepages)));total+=1
  absent=found-used
  if absent:missing.append(dict(chapter=c,references=sorted(absent)))
  entry=dict(chapter=c,title=re.sub(r'^\d+\s*','',g['title']),sourceFile=g['file'],summaryPage=summary['pdfPage'],summaryLocalPage=summary['localPage'],summaryPrintedPage=summary['pdfPage']-offset,groups=groups)
  output.append(entry);audit.append(dict(chapter=c,sourceFile=g['file'],sourceSha256=hashlib.sha256(path.read_bytes()).hexdigest(),summaryHeading=summary['title'],summaryPdfPage=summary['pdfPage'],summaryLocalPage=summary['localPage'],summaryPrintedPage=summary['pdfPage']-offset,numberedSummaryReferences=sorted(found),coveredReferences=sorted(used),uncoveredNumberedReferences=sorted(absent),groups=len(groups)))
 assert len(output)==44 and sorted(chapters)==list(range(1,45))
 data=dict(book=book['title'],authors=book['authors'],edition=book['edition'],printedOffset=offset,sourceHeading='Review & Summary',reviewedAt='2026-10-23',groupCount=total,equationCount=eqcount,chapters=output)
 dest=ROOT/'site/physics-formula-data.js';dest.write_text('/* Original mathematical transcriptions and teaching notes; generated by scripts/physics-formulas/author.py. */\nwindow.PHYSICS_FORMULAS='+json.dumps(data,ensure_ascii=False,separators=(',',':'))+';\n')
 (ROOT/'scripts/physics-formulas/source-audit.json').write_text(json.dumps(dict(book=book['title'],edition=book['edition'],reviewedAt=data['reviewedAt'],chapters=audit,groupCount=total,equationCount=eqcount),indent=2)+'\n')
 print(json.dumps(dict(chapters=len(output),groups=total,equations=eqcount,uncovered=missing),indent=2))
 if missing:raise SystemExit('Resolve uncovered numbered summary relations before release.')
if __name__=='__main__':build()
